def transform(grid):
    h,w=len(grid),len(grid[0])
    # Locate separator spacing and treat each open block as a cell.
    rs=[i for i,row in enumerate(grid) if all(v==8 for v in row)]
    cs=[j for j in range(w) if all(grid[i][j]==8 for i in range(h))]
    rh=[i for i in range(h) if i not in rs]
    cw=[j for j in range(w) if j not in cs]
    # block coordinate from separator-separated open strips
    rblocks=[]; cblocks=[]
    for i in rh:
        if not rblocks or i>rblocks[-1][-1]+1:rblocks.append([])
        rblocks[-1].append(i)
    for j in cw:
        if not cblocks or j>cblocks[-1][-1]+1:cblocks.append([])
        cblocks[-1].append(j)
    out=[row[:] for row in grid]
    seeds={2:[],3:[]}
    for ri,rr in enumerate(rblocks):
      for ci,cc in enumerate(cblocks):
        for r in rr:
          for c in cc:
            if grid[r][c] in seeds: seeds[grid[r][c]].append((ri,ci))
    paths={2:set(),3:set()}
    for color,pts in seeds.items():
      for a in pts:
       for b in pts:
        if a==b: continue
        if a[0]==b[0] or a[1]==b[1]:
         dr=0 if a[0]==b[0] else (1 if b[0]>a[0] else -1)
         dc=0 if a[1]==b[1] else (1 if b[1]>a[1] else -1)
         x,y=a
         while True:
          paths[color].add((x,y))
          if (x,y)==b: break
          x+=dr;y+=dc
    for ri,ci in paths[2]|paths[3]:
      color=6 if (ri,ci) in paths[2] and (ri,ci) in paths[3] else (2 if (ri,ci) in paths[2] else 3)
      for r in rblocks[ri]:
       for c in cblocks[ci]:out[r][c]=color
    return out
